#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif
#define TAU (2.0 * M_PI)

// Tests set this to render voices at unity so test/render.c can measure them.
int trommelsynthesizer_raw_gain = 0;

// Per-voice output gains, generated by `render --calibrate`.
#include "gains.h"

// ---- primitives ------------------------------------------------------------

typedef struct {
  double ic1, ic2, g, k, a1, a2, a3;
} Svf;

static void svf_set(Svf* s, double fc, double q, double sr) {
  if (fc > sr * 0.45)
    fc = sr * 0.45;
  s->g = tan(M_PI * fc / sr);
  s->k = 1.0 / q;
  s->a1 = 1.0 / (1.0 + s->g * (s->g + s->k));
  s->a2 = s->g * s->a1;
  s->a3 = s->g * s->a2;
}

static void svf_tick(Svf* s, double x, double* lp, double* bp, double* hp) {
  double v3 = x - s->ic2;
  double v1 = s->a1 * s->ic1 + s->a2 * v3;
  double v2 = s->ic2 + s->a2 * s->ic1 + s->a3 * v3;
  s->ic1 = 2 * v1 - s->ic1;
  s->ic2 = 2 * v2 - s->ic2;
  *bp = v1;
  *lp = v2;
  *hp = x - s->k * v1 - v2;
}

static inline double blep(double t, double dt) {
  if (t < dt) {
    t /= dt;
    return t + t - t * t - 1.0;
  }
  if (t > 1.0 - dt) {
    t = (t - 1.0) / dt;
    return t * t + t + t + 1.0;
  }
  return 0.0;
}

static inline double square(double ph, double dt) {
  double s = ph < 0.5 ? 1.0 : -1.0;
  s += blep(ph, dt);
  s -= blep(fmod(ph + 0.5, 1.0), dt);
  return s;
}

static inline double onepole_a(double fc, double sr) { return 1.0 - exp(-TAU * fc / sr); }

// ---- voice configuration ---------------------------------------------------

enum { K_NONE,
       K_SWEPT,
       K_SNARE,
       K_METAL,
       K_PING,
       K_CLAP,
       K_NOISE,
       K_SAMPLE };

typedef struct {
  uint8_t kind;
  float c[10];
} Cfg;

// K_SWEPT  c: f0 Hz, sweep amount, sweep tau, amp tau, click, click lp Hz,
//             drive, noise body, tone->drive (0/1)
// K_SNARE  c: osc1 Hz, osc2 Hz, osc1 tau, osc2 tau, pitch drop, noise hp Hz,
//             noise lp Hz, noise tau, noise level, snap click
// K_METAL  c: freq scale, bp Hz, hp Hz, fast tau, slow tau, slow mix,
//             noise fraction, click
// K_PING   c: f1, f2, tau1, tau2, mix2, bp Hz (0 = none), drive, squares (0/1),
//             tail mix, tail tau
// K_CLAP   c: bp Hz, Q, burst spacing, bursts, burst tau, tail tau, tail level,
//             hp Hz
// K_NOISE  c: hp Hz, attack tau, decay tau
#define SW(f0, amt, ftau, atau, click, clk, drv, nb, td)      \
  {                                                           \
    K_SWEPT, { f0, amt, ftau, atau, click, clk, drv, nb, td } \
  }
#define SN(o1, o2, t1, t2, drop, hp, lp, nt, nl, snap)      \
  {                                                         \
    K_SNARE, { o1, o2, t1, t2, drop, hp, lp, nt, nl, snap } \
  }
#define MT(sc, bp, hp, tf, ts, mix, nz, clk)      \
  {                                               \
    K_METAL, { sc, bp, hp, tf, ts, mix, nz, clk } \
  }
#define PG(f1, f2, t1, t2, m2, bp, drv, sq, tm, tt)     \
  {                                                     \
    K_PING, { f1, f2, t1, t2, m2, bp, drv, sq, tm, tt } \
  }
#define CL(bp, q, sp, n, bt, tt, tl, hp)     \
  {                                          \
    K_CLAP, { bp, q, sp, n, bt, tt, tl, hp } \
  }
#define NZ(hp, atk, dec)      \
  {                           \
    K_NOISE, { hp, atk, dec } \
  }
static const Cfg SAMPLE_CFG = {K_SAMPLE, {0}};

