// Analog voices come from CFG; anything else the machine has is a sample.
static const Cfg* cfg_for(int m, int v) {
  if (m < 0 || m >= M_COUNT || v < 0 || v >= V_COUNT)
    return NULL;
  if (CFG[m][v].kind != K_NONE)
    return &CFG[m][v];
  return sample_get(m, v) ? &SAMPLE_CFG : NULL;
}

bool eng_machine_has(int m, int v) { return cfg_for(m, v) != NULL; }

