bool eng_gm_lookup(int m, int key, int* voice, int* semis) {
  if (key < 35 || key > 81)
    return false;
  const Cand* c = GM[key - 35];
  for (int i = 0; i < 4 && c[i].v; i++) {
    if (eng_machine_has(m, c[i].v - 1)) {
      *voice = c[i].v - 1;
      *semis = c[i].s;
      return true;
    }
  }
  return false;
}

// ---- engine ----------------------------------------------------------------

typedef struct {
  bool active;
  int machine, voice;
  const Cfg* cfg;
  double t, dt, sr;
  double gain, vel;
  double choke;  // >0: ramping out, seconds left
  float p[P_COUNT];
  // working constants, set at trigger
  double f0, famt, ftau, atau, click, drive, nbody;
  double ph[6], fr[6];
  double aux[8];
  Svf s1, s2, s3;
  double lp1, lp2, ca;
  uint32_t rng;
  // samples
  const Sample* smp;
  double pos, step;
  double tone_lp, tone_a;
} Voice;

struct Engine {
  double sr;
  int machine;
  float master;
  float vp[V_COUNT][P_COUNT];
  Voice voices[V_COUNT];
};

static inline double rnd(Voice* v) {
  v->rng ^= v->rng << 13;
  v->rng ^= v->rng >> 17;
  v->rng ^= v->rng << 5;
  return (double)(int32_t)v->rng / 2147483648.0;
}

static inline double decay_scale(double d) { return pow(2.0, (d - 0.5) * 3.0); }
static inline double tone_scale(double t, double range) { return pow(2.0, (t - 0.5) * range); }

static const double METAL[6] = {205.3, 304.4, 369.6, 522.7, 540.0, 800.0};

static void voice_init(Voice* v, int semis) {
  const Cfg* c = v->cfg;
  const float* p = v->p;
  double tr = pow(2.0, (p[P_TUNE] + semis) / 12.0);
  double ds = decay_scale(p[P_DECAY]);
  double tn = p[P_TONE];
  double ex = p[P_EXTRA];
  v->t = 0;
  v->rng = 0x9E3779B9u ^ (uint32_t)(v->voice * 2654435761u);
  v->lp1 = v->lp2 = 0;
  memset(v->ph, 0, sizeof v->ph);
  memset(&v->s1, 0, sizeof v->s1);
  memset(&v->s2, 0, sizeof v->s2);
  memset(&v->s3, 0, sizeof v->s3);
  switch (c->kind) {
    case K_SWEPT:
      v->f0 = c->c[0] * tr;
      v->famt = c->c[1];
      v->ftau = c->c[2];
      v->atau = c->c[3] * ds;
      v->click = c->c[4] * 2.0 * ex * (c->c[8] > 0 ? 1.0 : 2.0 * tn);
      v->ca = onepole_a(c->c[5] * (c->c[8] > 0 ? 1.0 : tone_scale(tn, 3.0)), v->sr);
      v->drive = c->c[6] * (c->c[8] > 0 ? 0.4 + 1.2 * tn : 1.0);
      v->nbody = c->c[7];
      break;
    case K_SNARE:
      v->aux[0] = c->c[0] * tr;
      v->aux[1] = c->c[1] * tr;
      v->aux[2] = c->c[2] * ds;
      v->aux[3] = c->c[3] * ds;
      v->aux[4] = c->c[7] * ds * (0.6 + 0.8 * ex);
      v->aux[5] = c->c[8] * (0.3 + 1.4 * ex);
      v->aux[6] = 0.5 + tn;  // osc2 balance
      svf_set(&v->s1, c->c[5], 0.7, v->sr);
      v->ca = onepole_a(c->c[6] * tone_scale(tn, 2.0), v->sr);
      break;
    case K_METAL:
      for (int i = 0; i < 6; i++) v->fr[i] = METAL[i] * c->c[0] * tr;
      svf_set(&v->s1, c->c[1] * tr, 1.2, v->sr);
      svf_set(&v->s2, c->c[2] * tone_scale(tn, 1.2), 0.7, v->sr);
      v->aux[0] = c->c[3] * ds;
      v->aux[1] = c->c[4] * ds;
      v->aux[2] = fmin(1.0, fmax(0.0, c->c[5] * (0.4 + 1.2 * tn)));
      break;
    case K_PING:
      v->aux[0] = c->c[0] * tr;
      v->aux[1] = c->c[1] * tr;
      v->aux[2] = c->c[2] * ds;
      v->aux[3] = c->c[3] * ds;
      v->aux[4] = c->c[4] * (0.4 + 1.2 * tn);
      v->aux[5] = c->c[9] * ds;
      if (c->c[5] > 0)
        svf_set(&v->s1, c->c[5] * tr, 1.5, v->sr);
      break;
    case K_CLAP:
      svf_set(&v->s1, c->c[0] * tone_scale(tn, 1.0), c->c[1], v->sr);
      svf_set(&v->s2, c->c[7], 0.7, v->sr);
      v->aux[0] = c->c[5] * ds;
      break;
    case K_NOISE:
      svf_set(&v->s1, c->c[0] * tone_scale(tn, 1.0), 0.7, v->sr);
      v->aux[0] = c->c[2] * ds;
      break;
    default:
      break;
  }
}

static void sample_init(Voice* v, int semis) {
  v->smp = sample_get(v->machine, v->voice);
  v->pos = 0;
  double tr = pow(2.0, (v->p[P_TUNE] + semis) / 12.0);
  v->step = (double)v->smp->rate / v->sr * tr;
  double d = v->p[P_DECAY];
  v->aux[0] = d >= 0.5 ? 0.0 : 0.02 * pow(40.0, d * 2.0);  // decay tau, 0 = off
  v->tone_lp = 0;
  double t = v->p[P_TONE];
  v->aux[1] = t < 0.5 ? onepole_a(400.0 * pow(50.0, t * 2.0), v->sr) : 0.0;
  v->aux[2] = t > 0.5 ? (t - 0.5) * 2.0 * 1.0 : 0.0;  // shelf boost amount
  v->tone_a = onepole_a(3000.0, v->sr);
}

static inline double smp_at(const Sample* s, int64_t i) {
  if (i < 0 || (uint32_t)i >= s->frames)
    return 0.0;
  return (int16_t)(s->data[2 * i] | (s->data[2 * i + 1] << 8)) / 32768.0;
}

static double tick_sample(Voice* v) {
  const Sample* s = v->smp;
  int64_t i = (int64_t)v->pos;
  double f = v->pos - (double)i;
  double a = smp_at(s, i - 1), b = smp_at(s, i), c = smp_at(s, i + 1), d = smp_at(s, i + 2);
  double x = b + 0.5 * f * (c - a + f * (2 * a - 5 * b + 4 * c - d + f * (3 * (b - c) + d - a)));
  v->pos += v->step;
  if (v->pos >= s->frames)
    v->active = false;
  if (v->aux[0] > 0)
    x *= exp(-v->t / v->aux[0]);
  if (v->aux[1] > 0) {
    v->tone_lp += v->aux[1] * (x - v->tone_lp);
    x = v->tone_lp;
  } else if (v->aux[2] > 0) {
    v->lp2 += v->tone_a * (x - v->lp2);
    x += (x - v->lp2) * v->aux[2];
  }
  return x;
}

static double tick_swept(Voice* v) {
  double t = v->t;
  double f = v->f0 * (1.0 + v->famt * exp(-t / v->ftau));
  v->ph[0] += f / v->sr;
  v->ph[0] -= floor(v->ph[0]);
  double e = exp(-t / v->atau);
  double x = sin(TAU * v->ph[0]) * e;
  double n = rnd(v);
  v->lp1 += v->ca * (n - v->lp1);
  x += v->lp1 * exp(-t / 0.0015) * v->click;
  if (v->nbody > 0) {
    v->lp2 += 0.2 * (n - v->lp2);
    x += v->lp2 * e * e * v->nbody;
  }
  if (t > 0.01 && e < 0.0005)
    v->active = false;
  return tanh(v->drive * x) / tanh(v->drive);
}

static double tick_snare(Voice* v) {
  double t = v->t, dt = 1.0 / v->sr;
  const double* a = v->aux;
  double drop = v->cfg->c[4];
  double f1 = a[0] * (1.0 + drop * exp(-t / 0.015));
  double f2 = a[1] * (1.0 + drop * exp(-t / 0.015));
  v->ph[0] += f1 * dt;
  v->ph[1] += f2 * dt;
  v->ph[0] -= floor(v->ph[0]);
  v->ph[1] -= floor(v->ph[1]);
  double e1 = exp(-t / a[2]), e2 = exp(-t / a[3]);
  double body = sin(TAU * v->ph[0]) * e1 * 0.75 + sin(TAU * v->ph[1]) * e2 * 0.5 * a[6];
  double n = rnd(v), lp, bp, hp;
  svf_tick(&v->s1, n, &lp, &bp, &hp);
  v->lp1 += v->ca * (hp - v->lp1);
  double ne = exp(-t / a[4]);
  double x = body * 0.6 + v->lp1 * ne * a[5] * 0.5;
  x += rnd(v) * exp(-t / 0.0007) * v->cfg->c[9];
  if (t > 0.02 && e1 < 0.0005 && e2 < 0.0005 && ne < 0.0005)
    v->active = false;
  return x;
}

static double tick_metal(Voice* v) {
  double t = v->t, dt = 1.0 / v->sr;
  double s = 0;
  for (int i = 0; i < 6; i++) {
    v->ph[i] += v->fr[i] * dt;
    v->ph[i] -= floor(v->ph[i]);
    s += square(v->ph[i], v->fr[i] * dt);
  }
  s /= 3.0;
  double nf = v->cfg->c[6];
  double x = s * (1.0 - nf) + rnd(v) * nf * 0.8;
  double lp, bp, hp, lp2, bp2, hp2;
  svf_tick(&v->s1, x, &lp, &bp, &hp);
  svf_tick(&v->s2, bp * 1.5 + x * 0.3, &lp2, &bp2, &hp2);
  double e = (1.0 - v->aux[2]) * exp(-t / v->aux[0]) + v->aux[2] * exp(-t / v->aux[1]);
  double click = rnd(v) * exp(-t / 0.0008) * v->cfg->c[7];
  if (t > 0.01 && e < 0.0003)
    v->active = false;
  return (hp2 + click * 0.5) * e;
}

static double tick_ping(Voice* v) {
  double t = v->t, dt = 1.0 / v->sr;
  const double* a = v->aux;
  bool sq = v->cfg->c[7] > 0;
  v->ph[0] += a[0] * dt;
  v->ph[1] += a[1] * dt;
  v->ph[0] -= floor(v->ph[0]);
  v->ph[1] -= floor(v->ph[1]);
  double x, e;
  if (sq) {
    x = square(v->ph[0], a[0] * dt) + square(v->ph[1], a[1] * dt) * a[4];
    double tm = v->cfg->c[8];
    e = (1.0 - tm) * exp(-t / a[2]) + tm * exp(-t / a[5]);
    double lp, bp, hp;
    svf_tick(&v->s1, x, &lp, &bp, &hp);
    x = bp * e;
  } else {
    double e1 = exp(-t / a[2]), e2 = exp(-t / a[3]);
    x = sin(TAU * v->ph[0]) * e1 + sin(TAU * v->ph[1]) * a[4] * e2;
    double dr = v->cfg->c[6];
    x = tanh(dr * x) / tanh(dr);
    e = fmax(e1, e2);
  }
  if (t > 0.005 && e < 0.0005)
    v->active = false;
  return x;
}

static double tick_clap(Voice* v) {
  double t = v->t;
  const Cfg* c = v->cfg;
  double sp = c->c[2], nb = c->c[3], bt = c->c[4], tl = c->c[6];
  double e;
  if (t < nb * sp) {
    e = exp(-fmod(t, sp) / bt);
  } else {
    double tt = t - nb * sp;
    e = exp(-tt / bt) + tl * exp(-tt / v->aux[0]);
  }
  double n = rnd(v), lp, bp, hp, lp2, bp2, hp2;
  svf_tick(&v->s1, n, &lp, &bp, &hp);
  svf_tick(&v->s2, bp, &lp2, &bp2, &hp2);
  if (t > nb * sp + 0.01 && e < 0.0005)
    v->active = false;
  return hp2 * e;
}

static double tick_noise(Voice* v) {
  double t = v->t;
  double n = rnd(v), lp, bp, hp;
  svf_tick(&v->s1, n, &lp, &bp, &hp);
  double e = (1.0 - exp(-t / v->cfg->c[1])) * exp(-t / v->aux[0]);
  if (t > 0.005 && e < 0.0005)
    v->active = false;
  return hp * e;
}

static double voice_tick(Voice* v) {
  double x = 0;
  switch (v->cfg->kind) {
    case K_SWEPT:
      x = tick_swept(v);
      break;
    case K_SNARE:
      x = tick_snare(v);
      break;
    case K_METAL:
      x = tick_metal(v);
      break;
    case K_PING:
      x = tick_ping(v);
      break;
    case K_CLAP:
      x = tick_clap(v);
      break;
    case K_NOISE:
      x = tick_noise(v);
      break;
    case K_SAMPLE:
      x = tick_sample(v);
      break;
    default:
      v->active = false;
  }
  v->t += v->dt;
  if (v->choke > 0) {
    x *= v->choke / 0.004;
    v->choke -= v->dt;
    if (v->choke <= 0)
      v->active = false;
  }
  return x * v->gain;
}

Engine* eng_create(double sr) {
  Engine* e = calloc(1, sizeof *e);
  e->sr = sr > 0 ? sr : 48000.0;
  e->master = 1.0f;
  for (int v = 0; v < V_COUNT; v++) {
    e->vp[v][P_LEVEL] = 0.8f;
    e->vp[v][P_TUNE] = 0.0f;
    e->vp[v][P_DECAY] = 0.5f;
    e->vp[v][P_TONE] = 0.5f;
    e->vp[v][P_EXTRA] = 0.5f;
  }
  return e;
}

void eng_destroy(Engine* e) { free(e); }

void eng_reset(Engine* e) {
  for (int v = 0; v < V_COUNT; v++) e->voices[v].active = false;
}

void eng_trigger(Engine* e, int machine, int voice, int semis, float vel) {
  if (!eng_machine_has(machine, voice))
    return;
  Voice* v = &e->voices[voice];
  memset(v, 0, sizeof *v);
  v->machine = machine;
  v->voice = voice;
  v->cfg = cfg_for(machine, voice);
  v->sr = e->sr;
  v->dt = 1.0 / e->sr;
  memcpy(v->p, e->vp[voice], sizeof v->p);
  v->vel = vel;
  double k = 1.0;
  if (!trommelsynthesizer_raw_gain)
    k = K_GAIN[machine][voice];
  v->gain = e->master * v->p[P_LEVEL] * vel * k;
  if (v->cfg->kind == K_SAMPLE)
    sample_init(v, semis);
  else
    voice_init(v, semis);
  v->active = true;
  // Closed hat chokes the open hat, as on the real machines.
  if (voice == V_CH && e->voices[V_OH].active && e->voices[V_OH].choke <= 0)
    e->voices[V_OH].choke = 0.004;
}

void eng_note_on(Engine* e, int key, float vel) {
  int v, s;
  if (eng_gm_lookup(e->machine, key, &v, &s))
    eng_trigger(e, e->machine, v, s, vel);
}

static inline float softclip(float x) {
  float a = fabsf(x);
  if (a <= 0.8f)
    return x;
  float y = 0.8f + 0.2f * tanhf((a - 0.8f) / 0.2f);
  return x < 0 ? -y : y;
}

void eng_render(Engine* e, float* l, float* r, uint32_t n) {
  for (uint32_t i = 0; i < n; i++) {
    double sum = 0;
    for (int v = 0; v < V_COUNT; v++) {
      if (e->voices[v].active)
        sum += voice_tick(&e->voices[v]);
    }
    float y = trommelsynthesizer_raw_gain ? (float)sum : softclip((float)sum);
    l[i] = r[i] = y;
  }
}

// ---- params ----------------------------------------------------------------

void eng_set_param(Engine* e, uint32_t id, double value) {
  if (id == PID_MACHINE) {
    int m = (int)(value + 0.5);
    e->machine = m < 0 ? 0 : (m >= M_COUNT ? M_COUNT - 1 : m);
  } else if (id == PID_MASTER) {
    e->master = (float)value;
  } else if (id < PID_COUNT) {
    uint32_t k = id - 2;
    e->vp[k / P_COUNT][k % P_COUNT] = (float)value;
  }
}

double eng_get_param(const Engine* e, uint32_t id) {
  if (id == PID_MACHINE)
    return e->machine;
  if (id == PID_MASTER)
    return e->master;
  if (id < PID_COUNT) {
    uint32_t k = id - 2;
    return e->vp[k / P_COUNT][k % P_COUNT];
  }
  return 0;
}

static const char* const VOICE_ABBR[V_COUNT] = {"BD", "BD2", "SD", "SD2", "RS", "CP", "LT", "MT", "HT", "CH", "OH",
                                                "CY", "RD", "CB", "CB2", "TB", "LC", "MC", "HC", "TI", "MA", "CL"};
static const char* const VOICE_FULL[V_COUNT] = {
    "Bass Drum", "Bass Drum 2", "Snare", "Snare 2", "Rim Shot", "Hand Clap", "Low Tom", "Mid Tom", "High Tom",
    "Closed Hat", "Open Hat", "Crash", "Ride", "Cowbell", "Cowbell Low", "Tambourine", "Low Conga", "Mid Conga",
    "High Conga", "Timbale", "Maracas", "Claves"};
static const char* const PARAM_NAME[P_COUNT] = {"Level", "Tune", "Decay", "Tone", "Extra"};

#define L (1 << P_LEVEL)
#define T (1 << P_TUNE)
#define D (1 << P_DECAY)
#define N (1 << P_TONE)
#define X (1 << P_EXTRA)
// Which knobs each voice exposes (the ones its original had, plus Tone).
// clang-format off
static const uint8_t MASK[V_COUNT] = {
    [V_BD] = L | T | D | N | X, [V_BD2] = L | T | D | N,     [V_SD] = L | T | D | N | X,
    [V_SD2] = L | T | D | N | X, [V_RS] = L | T | N,         [V_CP] = L | D | N,
    [V_LT] = L | T | D | N,     [V_MT] = L | T | D | N,      [V_HT] = L | T | D | N,
    [V_CH] = L | T | D | N,     [V_OH] = L | T | D | N,      [V_CY] = L | T | D | N,
    [V_RD] = L | T | D | N,     [V_CB] = L | T | D | N,      [V_CB2] = L | T | D | N,
    [V_TB] = L | T | D | N,     [V_LC] = L | T | D | N,      [V_MC] = L | T | D | N,
    [V_HC] = L | T | D | N,     [V_TI] = L | T | D | N,      [V_MA] = L | D | N,
    [V_CL] = L | T | N,
};
// clang-format on
#undef L
#undef T
#undef D
#undef N
#undef X

const char* machine_name(int m) {
  static const char* const names[M_COUNT] = {
      [M_808] = "TR-808",
      [M_909] = "TR-909",
      [M_707] = "TR-707",
      [M_505] = "TR-505",
      [M_SDSV] = "SDS-V",
      [M_CR78] = "CR-78",
      [M_LINNDRUM] = "LinnDrum",
      [M_LM1] = "LM-1",
      [M_DMX] = "DMX",
      [M_DRUMULATOR] = "Drumulator",
      [M_DRUMTRAKS] = "Drumtraks",
      [M_MPC60] = "MPC60",
      [M_RX5] = "RX5",
      [M_RZ1] = "RZ-1",
      [M_SK1] = "SK-1",
      [M_KPR77] = "KPR-77",
      [M_DR55] = "DR-55",
      [M_DR110] = "DR-110",
      [M_TR606] = "TR-606",
      [M_RHYTHMACE] = "Rhythm Ace",
      [M_SPACEDRUM] = "Space Drum",
      [M_HR16] = "HR-16",
      [M_SDS5] = "SDS5",
  };
  return m >= 0 && m < M_COUNT ? names[m] : "?";
}

static void fill_info(uint32_t id, ParamInfo* o) {
  memset(o, 0, sizeof *o);
  o->id = id;
  if (id == PID_MACHINE) {
    snprintf(o->name, sizeof o->name, "Machine");
    snprintf(o->module, sizeof o->module, "Global");
    o->max = M_COUNT - 1;
    o->stepped = true;
    return;
  }
  if (id == PID_MASTER) {
    snprintf(o->name, sizeof o->name, "Master");
    snprintf(o->module, sizeof o->module, "Global");
    o->max = 1;
    o->def = 1.0;
    return;
  }
  uint32_t k = id - 2;
  int v = (int)(k / P_COUNT), p = (int)(k % P_COUNT);
  const char* pn = PARAM_NAME[p];
  if (p == P_EXTRA)
    pn = (v == V_BD) ? "Attack" : "Snappy";
  snprintf(o->name, sizeof o->name, "%s %s", VOICE_ABBR[v], pn);
  snprintf(o->module, sizeof o->module, "%s", VOICE_FULL[v]);
  o->min = p == P_TUNE ? -12 : 0;
  o->max = p == P_TUNE ? 12 : 1;
  o->def = p == P_LEVEL ? 0.8 : (p == P_TUNE ? 0.0 : 0.5);
}

uint32_t param_count(void) {
  uint32_t n = 2;
  for (int v = 0; v < V_COUNT; v++)
    for (int p = 0; p < P_COUNT; p++) n += (MASK[v] >> p) & 1;
  return n;
}

bool param_info(uint32_t index, ParamInfo* out) {
  if (index == 0) {
    fill_info(PID_MACHINE, out);
    return true;
  }
  if (index == 1) {
    fill_info(PID_MASTER, out);
    return true;
  }
  uint32_t n = 2;
  for (int v = 0; v < V_COUNT; v++)
    for (int p = 0; p < P_COUNT; p++)
      if ((MASK[v] >> p) & 1) {
        if (n++ == index) {
          fill_info(PID_VOICE(v, p), out);
          return true;
        }
      }
  return false;
}

bool param_info_by_id(uint32_t id, ParamInfo* out) {
  if (id >= PID_COUNT)
    return false;
  if (id >= 2) {
    uint32_t k = id - 2;
    if (!((MASK[k / P_COUNT] >> (k % P_COUNT)) & 1))
      return false;
  }
  fill_info(id, out);
  return true;
}

void param_text(uint32_t id, double value, char* out, uint32_t size) {
  if (id == PID_MACHINE) {
    snprintf(out, size, "%s", machine_name((int)(value + 0.5)));
  } else if (id >= 2 && (id - 2) % P_COUNT == P_TUNE) {
    snprintf(out, size, "%+.1f st", value);
  } else {
    snprintf(out, size, "%d%%", (int)(value * 100.0 + 0.5));
  }
}
